SELECT cs.id, cs.student_id AS studentId, su.realname AS studentName, cs.teaching_id AS teachingId, cs.course_id AS courseId, c.course_name AS courseName, c.course_code AS courseCode, tu.realname AS teacherName, cs.depart_id AS departId, d.depart_name AS departName, cs.semester, cs.academic_year AS academicYear, cs.status, cs.selected_at AS selectedAt FROM ( SELECT * FROM ainote_course_selection
${ew.customSqlSegment}
) cs LEFT JOIN sys_user su ON cs.student_id = su.id LEFT JOIN ainote_teaching t ON cs.teaching_id = t.id LEFT JOIN sys_user tu ON t.teacher_id = tu.id LEFT JOIN ainote_course c ON cs.course_id = c.id LEFT JOIN sys_depart d ON cs.depart_id = d.id
